<?php
declare(strict_types=1);
namespace Modules\Integrations;

final class Config
{
    public static function assertSecretRevision(array $secret,int $revision): void {
        if (array_key_exists('_owner_bound_revision',$secret)
            && (!is_int($secret['_owner_bound_revision']) || $secret['_owner_bound_revision'] !== $revision)) {
            throw new \RuntimeException('CREDENTIAL_REVISION_CONFLICT');
        }
    }
    public static function root(): string {return defined('APP_ROOT')?APP_ROOT:dirname(__DIR__,2);}
    public static function key(): string {$dir=self::root().'/private/integrations';if(!is_dir($dir)&&!mkdir($dir,0700,true))throw new \RuntimeException('PRIVATE_DIRECTORY_FAILED');$p=$dir.'/key';if(is_link($p))throw new \RuntimeException('PRIVATE_KEY_LINK');if(!is_file($p)){$f=@fopen($p,'xb');if($f){fwrite($f,random_bytes(32));fclose($f);chmod($p,0600);}}$k=file_get_contents($p);if(!is_string($k)||strlen($k)!==32)throw new \RuntimeException('PRIVATE_KEY_INVALID');return $k;}
    public static function store(): PrivateStore {return new PrivateStore(self::root().'/private/integrations/blobs',self::key());}
    public static function secrets(string $provider): array {Support::provider($provider);$p=self::root().'/private/integrations/'.$provider.'.enc';if(!is_file($p))return [];$raw=file_get_contents($p);if(!is_string($raw)||strlen($raw)<29)throw new \RuntimeException('SECRET_STORE_CORRUPT');$plain=openssl_decrypt(substr($raw,28),'aes-256-gcm',self::key(),OPENSSL_RAW_DATA,substr($raw,0,12),substr($raw,12,16),$provider);if($plain===false)throw new \RuntimeException('SECRET_STORE_CORRUPT');return json_decode($plain,true,32,JSON_THROW_ON_ERROR);}
    public static function saveSecrets(string $provider,array $values): void {Support::provider($provider);$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt(Support::json($values),'aes-256-gcm',self::key(),OPENSSL_RAW_DATA,$iv,$tag,$provider);if($cipher===false)throw new \RuntimeException('SECRET_ENCRYPT_FAILED');$p=self::root().'/private/integrations/'.$provider.'.enc';$tmp=$p.'.'.bin2hex(random_bytes(6));if(file_put_contents($tmp,$iv.$tag.$cipher)!==strlen($iv.$tag.$cipher))throw new \RuntimeException('SECRET_WRITE_FAILED');chmod($tmp,0600);if(!rename($tmp,$p))throw new \RuntimeException('SECRET_WRITE_FAILED');}
    public static function get(\PDO $db,string $provider): array {Support::provider($provider);$q=$db->prepare('SELECT * FROM integration_connections WHERE provider=?');$q->execute([$provider]);$r=$q->fetch(\PDO::FETCH_ASSOC);return $r?:['provider'=>$provider,'enabled'=>0,'revision'=>0,'display_name'=>Support::PROVIDERS[$provider],'config_json'=>'{}','last_status'=>'unconfigured'];}
    public static function bankIdentity(\PDO $db): array {$bank=self::get($db,'bank');$one=self::get($db,'onec');$public=Support::decode($one['config_json']);$q=$db->query("SELECT selected_profile,source_receipt_sha256,source_revision FROM integration_configuration_sources WHERE provider='onec'");$source=$q->fetch(\PDO::FETCH_ASSOC);return ['policy'=>'source-bank-shared-operative-onec-v1','bank_revision'=>(int)$bank['revision'],'bank_enabled'=>(bool)$bank['enabled'],'credential_provider'=>'onec','onec_revision'=>(int)$one['revision'],'onec_enabled'=>(bool)$one['enabled'],'effective_reference'=>self::reference((string)($public['access_reference']??'')),'selected_source_reference'=>$source['selected_profile']??null,'selected_source_revision'=>isset($source['source_revision'])?(int)$source['source_revision']:null,'source_receipt_sha256'=>$source['source_receipt_sha256']??null];}
    public static function validatePublic(string $provider,array $config): void {
        Support::provider($provider);Support::business($config);
        if(!in_array($provider,['email','max'],true)){
            if(array_diff(array_keys($config),['label','access_reference','timeout_seconds','note']))throw new \InvalidArgumentException('POD_PUBLIC_FIELDS_ONLY');self::reference((string)($config['access_reference']??''));$timeout=$config['timeout_seconds']??300;if(!is_int($timeout)||$timeout<30||$timeout>900||mb_strlen((string)($config['label']??''))>200||mb_strlen((string)($config['note']??''))>4000)throw new \InvalidArgumentException('INVALID_PUBLIC_CONFIG');
        }elseif($provider==='email'){
            if(array_diff(array_keys($config),['host','port','security','username','from_email','from_name']))throw new \InvalidArgumentException('EMAIL_PUBLIC_FIELDS_ONLY');foreach(['host','username','from_email','from_name'] as $key)if(isset($config[$key])&&(!is_string($config[$key])||preg_match('/[\x00-\x1f\x7f]/',$config[$key])))throw new \InvalidArgumentException('INVALID_HEADER_CONFIG');if(mb_strlen($config['username']??'')>320||mb_strlen($config['from_name']??'')>120)throw new \InvalidArgumentException('INVALID_PUBLIC_CONFIG');
        }elseif($config)throw new \InvalidArgumentException('MAX_PUBLIC_FIELDS_ONLY');
    }
    public static function save(\PDO $db,string $provider,array $config,int $expected,bool $enabled): void {self::validatePublic($provider,$config);$ownTransaction=!$db->inTransaction();if($ownTransaction)$db->beginTransaction();try{$q=$db->prepare('SELECT revision FROM integration_connections WHERE provider=? FOR UPDATE');$q->execute([$provider]);$revision=$q->fetchColumn();if((int)($revision?:0)!==$expected)throw new \RuntimeException('REVISION_CONFLICT');$db->prepare('INSERT INTO integration_connections(provider,enabled,revision,display_name,config_json,last_status) VALUES(?,?,?,?,?,\'unverified\') ON DUPLICATE KEY UPDATE enabled=VALUES(enabled),revision=VALUES(revision),config_json=VALUES(config_json),last_status=\'unverified\',updated_at=NOW(6)')->execute([$provider,(int)$enabled,$expected+1,Support::PROVIDERS[$provider],Support::json($config)]);if($provider==='onec')$db->exec("UPDATE integration_connections SET last_status='unverified',last_checked_at=NULL WHERE provider='bank'");if($ownTransaction)$db->commit();}catch(\Throwable $e){if($ownTransaction&&$db->inTransaction())$db->rollBack();throw $e;}}
    public static function liveAllowed(): bool {return getenv('IPPHP_ALLOW_EXTERNAL')==='owner-authorized-project-access';}
    /** Manual SMTP access only; does not enable providers, workers or rental outbox. */
    public static function emailLiveAllowed(): bool {return getenv('IPPHP_ALLOW_EMAIL')==='owner-authorized-email-access';}
    public static function reference(string $reference): string {if($reference==='')return 'default';if(!preg_match('/^[A-Za-z][A-Za-z0-9_.-]{0,79}$/D',$reference))throw new \InvalidArgumentException('INVALID_PROFILE_REFERENCE');return $reference;}
    public static function profile(string $provider,string $reference=''): array {$provider=$provider==='bank'?'onec':$provider;$reference=self::reference($reference);$all=self::secrets($provider);$value=$all['profiles'][$reference]??[];if(!is_array($value))throw new \RuntimeException('PRIVATE_PROFILE_INVALID');return $value+['_reference'=>$reference];}
    public static function saveProfile(string $provider,string $reference,array $value): void {$provider=$provider==='bank'?'onec':$provider;$reference=self::reference($reference);unset($value['_reference']);$all=self::secrets($provider);$all['profiles'][$reference]=$value;self::saveSecrets($provider,$all);}
}
